import {KartGame,ITEMS,TRACK,TRACK_LENGTH,trackAt} from './kart-engine.js';
import {KartView} from './kart-renderer.js';
import {loadWords} from './word-store.js';
import {readWords} from './vocab.js';
import {partyFX} from './party-fx.js';
import {bindGameLifecycle} from './game-lifecycle.js';
const $=id=>document.getElementById(id),screens=['intro','quiz','feedback','result','reviewDone'];
let game,view,ready=false,last=0,raf=0,bannerTimer=0,muted=true,audio=null,lastCount=-1,lastRank=6,hudClock=0,disposed=false,contextLost=false,recovering=false,needsRender=true;
const held=new Map(),keys=new Set(),map=$('map').getContext('2d');
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
function tone(kind='good'){if(muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const notes=kind==='win'?[523,659,784,1047,1319]:kind==='miss'?[330,220]:kind==='boost'?[330,660,990]:[660,880];notes.forEach((hz,i)=>{const o=audio.createOscillator(),v=audio.createGain(),t=audio.currentTime+i*.09;o.type='triangle';o.frequency.value=hz;v.gain.setValueAtTime(0,t);v.gain.linearRampToValueAtTime(.065,t+.01);v.gain.exponentialRampToValueAtTime(.001,t+.2);o.connect(v);v.connect(audio.destination);o.start(t);o.stop(t+.21);});}catch{}}
$('sound').onclick=()=>{muted=!muted;$('sound').textContent=muted?'音 OFF':'音 ON';$('sound').setAttribute('aria-pressed',String(!muted));if(!muted)tone();};
function banner(text){clearTimeout(bannerTimer);const el=$('banner');el.textContent=text;el.className='race-banner';void el.offsetWidth;el.classList.add('show');bannerTimer=setTimeout(()=>el.classList.remove('show'),1500);}
function clear(){held.clear();keys.clear();game?.clearInput();for(const id of ['left','right','drift','brake'])$(id).classList.remove('pressed');}
function controls(){let left=keys.has('ArrowLeft')||keys.has('KeyA'),right=keys.has('ArrowRight')||keys.has('KeyD'),drift=keys.has('Space'),brake=keys.has('ArrowDown');for(const v of held.values()){if(v==='left')left=true;if(v==='right')right=true;if(v==='drift')drift=true;if(v==='brake')brake=true;}game.input(Number(right)-Number(left),drift,brake);for(const [id,value]of[['left',left],['right',right],['drift',drift],['brake',brake]])$(id).classList.toggle('pressed',value);}
for(const id of ['left','right','drift','brake']){const el=$(id);el.addEventListener('pointerdown',e=>{if(game?.phase!=='race'||game.paused||e.button>0)return;e.preventDefault();held.set(e.pointerId,id);try{el.setPointerCapture(e.pointerId);}catch{}controls();});for(const type of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(type,e=>{if(held.get(e.pointerId)===id){if(type!=='pointerup'){clear();return;}held.delete(e.pointerId);controls();}});el.addEventListener('contextmenu',e=>e.preventDefault());}
// Capture can fail in embedded browsers: window release still clears the held pointer.
for(const type of ['pointerup','pointercancel'])window.addEventListener(type,e=>{if(!held.has(e.pointerId))return;if(type==='pointercancel'){clear();return;}held.delete(e.pointerId);controls();});
window.addEventListener('keydown',e=>{if(game?.phase!=='race'||game.paused)return;if(['ArrowLeft','ArrowRight','KeyA','KeyD','Space','ArrowDown'].includes(e.code)){e.preventDefault();keys.add(e.code);controls();}if(e.code==='KeyX'&&!e.repeat){e.preventDefault();action(()=>game.useItem());}});window.addEventListener('keyup',e=>{if(keys.delete(e.code))controls();});
function pause(value){if(!ready||!game||['ready','done','reviewDone'].includes(game.phase))return;clear();game.pause(value);$('pauseScreen').hidden=!value;if(value){clearTimeout(bannerTimer);$('banner').className='race-banner';partyFX.clear();$('resume').focus();}else{if(game.phase==='countdown')lastCount=-1;if(game.phase==='race')$('left').focus();}}
bindGameLifecycle(window,document,{clearInput:clear,pause});$('pause').onclick=()=>pause(true);$('resume').onclick=()=>pause(false);
const timeLabel=t=>{const ticks=Math.floor(t*10);return Math.floor(ticks/600)+':'+((ticks%600)/10).toFixed(1).padStart(4,'0');};
function show(id){for(const s of screens)$(s).hidden=s!==id;}
function action(fn){if(!game)return;const before=game.phase;fn();if(before!==game.phase)renderPhase();events();hud();}
function makeGame(){const p=readWords(loadWords());if(p.errors.length)throw Error(p.errors[0]);return new KartGame(p.entries,{rolling:true});}
function start(){if(!ready)return;try{game=makeGame();}catch(e){$('error').textContent=e.message;return;}view.setGame(game);$('roadQuiz').hidden=true;$('gateAnswer').hidden=true;clear();partyFX.resetRewards();lastCount=-1;lastRank=6;$('pauseScreen').hidden=true;action(()=>game.start());}
function renderPhase(){needsRender=true;clear();switch(game.phase){case'countdown':case'race':show(null);break;case'quiz':{show('quiz');$('quizLabel').textContent=game.isReview?'PIT REVIEW · '+(game.reviewIndex+1)+' / '+game.reviewWords.length:'WORD GATE · '+(game.gate+1)+' / 9';$('question').textContent=game.reverse?game.pair.meaning:game.pair.word;$('direction').textContent=game.reverse?'この意味に合う英語を選ぼう':'この英語の意味を選ぼう';$('choices').replaceChildren();game.options.forEach((p,i)=>{const b=document.createElement('button');b.textContent=game.reverse?p.word:p.meaning;b.onclick=()=>action(()=>game.answer(i));$('choices').append(b);});break;}case'feedback':{show('feedback');$('feedbackKicker').textContent=game.lastCorrect?'NICE ANSWER!':'CHECK THE WORD';$('feedbackTitle').textContent=game.lastCorrect?'正解！':'正しい組を覚えよう';$('answerWord').textContent=game.pair.word;$('answerMeaning').textContent=game.pair.meaning;$('feedbackDetail').textContent=game.isReview?(game.lastCorrect?'覚え直せた！ 次へ進もう。':'意味を確認して、もう一度選ぼう。'):game.lastCorrect?'ターボ獲得！ アイテムを使って抜き返そう。':'今回はターボなし。あとでもう一度練習しよう。';$('continue').textContent=game.isReview?'次へ':'レースへ！';break;}case'done':{show('result');$('resultRank').textContent=game.finishedRank+'位！';$('trophy').textContent=game.finishedRank<=3?['🏆','🥈','🥉'][game.finishedRank-1]:'🏁';$('resultCorrect').textContent=game.correct+' / 9';$('resultStars').textContent='★ '+game.starTotal;$('resultTime').textContent=timeLabel(game.time);$('resultDrifts').textContent=game.driftCount+' 回';$('reviewButton').hidden=!game.misses.size;$('reviewIntro').textContent=game.misses.size?'取り違えた '+game.misses.size+' 語を、ピットで覚え直そう！':'全ゲート正解！ 次は自己ベストに挑もう。';$('reviewList').replaceChildren();for(const p of game.misses.values()){const el=document.createElement('p');el.textContent=p.word+' → '+p.meaning;$('reviewList').append(el);}try{const old=Number(localStorage.getItem('party-kart-best-v2'))||Infinity;const next=Math.min(old,game.time);localStorage.setItem('party-kart-best-v2',String(next));$('best').textContent=(game.time<old?'走行タイム更新！ ':'')+'ベスト '+timeLabel(next)+'（走行ゲート方式）';}catch{$('best').textContent='今回の記録を保存できませんでした。';}break;}case'reviewDone':show('reviewDone');partyFX.burst('win','復習クリア！');tone('win');break;}}
function events(){for(const e of game.events.splice(0)){if(e.type==='roadQuestion'){clear();roadPanel();}if(e.type==='roadAnswer'){roadPanel();banner(game.lastCorrect?'正解！ TURBO！':'次で取り返そう！');}if(e.type==='reward')partyFX.reward(e.key,e.label,e.points);if(e.type==='go'){banner('GO！');tone('boost');$('message').textContent='カーブでドリフト！ 正解ターボでトップを狙え。';}if(e.type==='drift'){banner(e.level===2?'SUPER TURBO！':'MINI TURBO！');tone('boost');}if(e.type==='lap'){banner(e.lap===3?'FINAL LAP！':'LAP '+e.lap);tone('boost');}if(e.type==='coin')tone();if(e.type==='pad'){banner('DASH！');tone('boost');}if(e.type==='correct')tone('good');if(e.type==='wrong')tone('miss');if(e.type==='item'){banner(ITEMS[e.kind].name+'！');tone('boost');}if(e.type==='noTarget')$('message').textContent='前方70mに相手がいない！ パルスは残しておこう。';if(e.type==='hitRival')$('message').textContent='パルス命中！ 前の1台がスローダウン。';if(e.type==='incoming'){$('message').textContent='攻撃が来る！ バブル・コメットで防げる！';tone('miss');}if(e.type==='blocked'){banner('GUARD！');$('message').textContent='ガード成功！ そのまま抜き去ろう。';}if(e.type==='hit'){banner('SPIN！');tone('miss');$('message').textContent='スピン！ 加速板や正解ターボで取り返そう。';}if(e.type==='finish'){partyFX.burst('win',game.finishedRank===1?'優勝！':'FINISH！');tone('win');}}}
function drawMap(){if(!map)return;map.clearRect(0,0,180,140);const project=p=>({x:90+p.x*.4,y:70+p.z*.38});map.strokeStyle='#ffffffb0';map.lineWidth=7;map.beginPath();TRACK.forEach((p,i)=>{const q=project(p);if(i===0)map.moveTo(q.x,q.y);else map.lineTo(q.x,q.y);});map.stroke();for(const [i,r]of[...game.ai,{distance:game.distance}].entries()){const p=project(trackAt(r.distance));map.beginPath();map.arc(p.x,p.y,i===5?5:3.5,0,Math.PI*2);map.fillStyle=i===5?'#ffdd46':['#63d8ff','#b48eff','#fff08c','#7ff2b1','#ff9acc'][i];map.fill();if(i===5){map.strokeStyle='#6c4615';map.lineWidth=2;map.stroke();}}}
function hud(){if(!game)return;roadHUD();const rank=game.phase==='done'?game.finishedRank:game.rank;$('rank').textContent=rank;$('lap').textContent='LAP '+game.lap+' / 3';$('time').textContent=timeLabel(game.time);$('coins').textContent='◆ '+game.coins+' / 8';$('accuracy').textContent='正解 '+game.correct+' / '+game.answered;$('speed').textContent=Math.round(game.speed*3.6)+' km/h';$('driftGauge').value=game.drift;$('driftLabel').textContent=game.drift>=1.8?'離して大ターボ！':game.drift>=.7?'離してターボ！':'カーブでためる';$('driftGauge').parentElement.classList.toggle('charged',game.drift>=1.8);const curve=trackAt(game.distance+25).curve;$('roadHint').textContent=Math.abs(game.lateral)>6.55?'コース外！ 道路へ戻ろう':Math.abs(curve)<.003?'ストレート':curve>0?'← 左カーブ':'右カーブ →';const item=ITEMS[game.item];$('itemIcon').textContent=item?.icon??'？';$('itemName').textContent=item?.name??'アイテム';$('itemHelp').textContent=item?.help??'単語に正解で獲得';$('item').disabled=!item||game.phase!=='race'||game.paused;for(const id of['left','right','drift','brake'])$(id).disabled=game.phase!=='race'||game.paused;$('warning').hidden=game.incoming<=0||game.phase!=='race';if(rank<lastRank&&game.phase==='race')$('message').textContent=rank+'位に浮上！ 次のゲートも正解しよう。';lastRank=rank;drawMap();}
function frame(t){if(disposed)return;const dt=last?Math.min((t-last)/1000,.1):.016;last=t;if(ready){const phase=game.phase;game.tick(dt);if(game.phase!==phase)renderPhase();events();if(game.phase==='countdown'&&!game.paused){const n=Math.max(1,Math.ceil(game.countdown));if(n!==lastCount){clearTimeout(bannerTimer);$('banner').textContent=n;$('banner').className='race-banner counting';lastCount=n;tone();}}if(needsRender||(!game.paused&&['race','countdown'].includes(game.phase))){try{view.render(dt);needsRender=false;}catch{renderFailure('描画エラーが発生しました');}}hudClock+=dt;if(hudClock>.08){hudClock=0;hud();}}raf=requestAnimationFrame(frame);}
$('start').onclick=start;$('again').onclick=start;$('retry').onclick=start;$('continue').onclick=()=>action(()=>game.continue());$('reviewButton').onclick=()=>action(()=>game.startReview());$('item').onclick=()=>action(()=>game.useItem());
function renderFailure(message){clear();game?.pause(true);ready=false;clearTimeout(bannerTimer);$('banner').className='race-banner';partyFX.clear();$('pauseScreen').hidden=false;$('pauseTitle').textContent=message;$('resume').disabled=false;$('resume').textContent='再読み込みする';$('resume').onclick=()=>location.reload();$('start').disabled=true;}
$('raceCanvas').addEventListener('webglcontextlost',e=>{e.preventDefault();contextLost=true;recovering=true;renderFailure('3D表示が中断されました');});
function restoreView(){contextLost=false;if(!view?.cars)return;try{view.resize();view.render(0);ready=true;recovering=false;last=0;needsRender=true;$('pauseTitle').textContent='3D表示を復旧しました';$('resume').textContent='続ける';$('resume').onclick=()=>{if(game.phase==='ready'){$('pauseScreen').hidden=true;game.pause(false);}else pause(false);};$('start').disabled=false;}catch{renderFailure('再読み込みが必要です');}}
// Three.js restores its GPU state in its own listener; recover only after every listener finishes.
$('raceCanvas').addEventListener('webglcontextrestored',()=>queueMicrotask(restoreView));
async function init(){try{game=makeGame();view=new KartView($('raceCanvas'),game);await view.load();if(contextLost){raf=requestAnimationFrame(frame);return;}if(recovering){restoreView();if(!ready){raf=requestAnimationFrame(frame);return;}}ready=true;$('start').disabled=false;$('start').textContent='グランプリに出場！';hud();raf=requestAnimationFrame(frame);}catch(e){view?.dispose();$('error').textContent='ゲームを開始できませんでした。'+(e.message.includes('単語')||e.message.includes('訳')?e.message:'画像の読み込み・3D表示を確認し、再読み込みしてください。');$('start').textContent='ゲーム選択からやり直す';}}
function resizeView(){if(window.visualViewport)document.documentElement.style.setProperty('--kart-height',Math.round(window.visualViewport.height)+'px');if(view&&!contextLost){view.resize();needsRender=true;}}window.addEventListener('resize',resizeView);window.visualViewport?.addEventListener('resize',resizeView);resizeView();window.addEventListener('pagehide',()=>{clear();clearTimeout(bannerTimer);});
init();

function roadPanel(){const active=game.roadQuestion; $('roadQuiz').hidden=!active;if(!active)return;$('roadWord').textContent=game.reverse?game.pair.meaning:game.pair.word;$('roadChoices').replaceChildren();game.options.forEach((p,i)=>{const b=document.createElement('button');b.textContent=(i+1)+' · '+(game.reverse?p.word:p.meaning);b.onclick=()=>game.chooseLane(i);$('roadChoices').append(b);});}
function roadHUD(){if(!game)return;$('roadQuiz').hidden=!game.roadQuestion;if(game.roadQuestion){$('roadDistance').textContent=(game.reverse?'英語を選ぶ · ':'意味を選ぶ · ')+'ゲートまで '+Math.max(0,Math.ceil((game.nextGate-game.distance)/Math.max(1,game.speed)))+' 秒 · 選ぶとそのレーンへ移動';const lane=Math.max(0,Math.min(3,Math.floor((game.lateral+7)/3.5)));Array.from($('roadChoices').children).forEach((b,i)=>b.setAttribute('aria-pressed',String(i===lane)));}const note=game.gateNotice;$('gateAnswer').hidden=!note||game.time>note.until;if(note)$('gateAnswer').textContent=(note.correct?'✓ 正解！ ':'✕ 正しくは ')+note.word+' → '+note.meaning;}

window.addEventListener('keydown',e=>{if(game?.roadQuestion&&!game.paused&&/^Digit[1-4]$/.test(e.code)){e.preventDefault();game.chooseLane(Number(e.code.slice(-1))-1);}});
